<template>
  <aside class="panel" aria-label="Настройки стеллажа">
    <div class="panel-title"><span class="label">ВАША КОНФИГУРАЦИЯ</span><button class="reset" @click="$emit('reset')">Сбросить ↺</button></div>
    <h2>Сделайте<br>его своим.</h2><p class="intro">Размер, ритм и цвет — под ваше пространство.</p>
    <div class="control-section"><h3><span>01</span> Габариты</h3><label v-for="dimension in dimensions" :key="dimension.key" class="range"><span>{{dimension.title}}<output :for="dimension.key">{{Math.round(config[dimension.key]*100)}} <small>см</small></output></span><input :id="dimension.key" type="range" :min="dimension.min" :max="dimension.max" step=".01" :value="config[dimension.key]" @input="setDimension(dimension.key,$event)"></label></div>
    <div class="control-section"><h3><span>02</span> Ритм полок</h3><div class="stepper-row"><span>По горизонтали</span><div class="stepper"><button aria-label="Уменьшить количество колонок" :disabled="config.cols<=1" @click="step('cols',-1)">−</button><output aria-live="polite">{{config.cols}}</output><button aria-label="Увеличить количество колонок" :disabled="config.cols>=6" @click="step('cols',1)">+</button></div></div><div class="stepper-row"><span>По вертикали</span><div class="stepper"><button aria-label="Уменьшить количество рядов" :disabled="config.rows<=1" @click="step('rows',-1)">−</button><output aria-live="polite">{{config.rows}}</output><button aria-label="Увеличить количество рядов" :disabled="config.rows>=6" @click="step('rows',1)">+</button></div></div></div>
    <fieldset class="control-section color-section"><legend><span>03</span> Отделка</legend><div class="colors"><label v-for="color in colors" :key="color.value" :title="color.name"><input type="radio" name="finish" :value="color.value" :checked="config.color===color.value" @change="config={...config,color:color.value}"><span :style="{background:color.value}"><i v-if="config.color===color.value" :style="{color:color.dark?'white':'#252923'}">✓</i></span><span class="sr-only">{{color.name}}</span></label></div><p class="color-name">{{colors.find(color=>color.value===config.color)?.name}} <span>Матовая поверхность</span></p></fieldset>
    <button class="download" @click="$emit('download')">Скачать конфигурацию <span>↓</span></button><p class="panel-note">JSON-файл с параметрами вашей модели.<br>Это эксперимент, а не заказ мебели.</p>
  </aside>
</template>
<script setup lang="ts">
import type {ShelfConfig} from '../types/shelf';
const config=defineModel<ShelfConfig>({required:true});
defineEmits<{reset:[];download:[]}>();
const dimensions=[{key:'width' as const,title:'Ширина',min:.5,max:2.4},{key:'height' as const,title:'Высота',min:.5,max:2.4},{key:'depth' as const,title:'Глубина',min:.2,max:.6}];
const colors=[{name:'Молочный',value:'#ede9df',dark:false},{name:'Тёплый дуб',value:'#b89165',dark:false},{name:'Шалфей',value:'#89947c',dark:false},{name:'Графит',value:'#454945',dark:true},{name:'Терракота',value:'#ae6d50',dark:true}];
function setDimension(key:'width'|'height'|'depth',event:Event){config.value={...config.value,[key]:Number((event.target as HTMLInputElement).value)};}
function step(key:'rows'|'cols',delta:number){config.value={...config.value,[key]:Math.min(6,Math.max(1,config.value[key]+delta))};}
</script>
